/**
 * Types for static image imports (`import photo from '@/public/images/x.jpg'`).
 *
 * Next.js normally provides these through next-env.d.ts, but that file is generated by
 * `next dev` / `next build` and is gitignored. CI runs `npm run typecheck` BEFORE `npm run
 * build`, on a fresh checkout, so it has no next-env.d.ts, and every static image import
 * failed with TS2307 (CI on 650cc0e). Referencing the image types here, in a committed file,
 * makes typecheck independent of whether a build has run.
 */
/// <reference types="next/image-types/global" />
